import { startPlayWriterCDPRelayServer } from 'playwriter/dist/cdp-relay.js';

/**
 * Browser Automation Module for O.G.R.E Grading Server
 *
 * Embeds Playwriter CDP relay server for browser automation.
 * O.G.R.E extension connects to this server (no separate Playwriter extension needed).
 */

// ============================================================================
// Session Store
// ============================================================================

/** @type {Map<string, SessionGrant>} */
const activeSessions = new Map();

/**
 * @typedef {Object} SessionGrant
 * @property {string} sessionToken - UUID generated by extension
 * @property {number} tabId - Chrome tab ID (for reference)
 * @property {string} url - Exact URL pattern allowed
 * @property {string} grantedBy - Extension ID that granted access
 * @property {Date} grantedAt - When the session was granted
 * @property {Date} expiresAt - When the session expires (1 hour default)
 * @property {string} scope - Permission scope (always 'automation' for now)
 */

// ============================================================================
// Embedded Playwriter CDP Relay Server
// ============================================================================

let relayServer = null;
let mcpServerRunning = false;

/**
 * Initialize the embedded Playwriter CDP relay server
 * O.G.R.E extension will connect to this server via WebSocket (port 19988)
 */
export async function initMCPServer() {
  if (mcpServerRunning) {
    console.log('[Automation] Playwriter CDP relay server already running');
    return;
  }

  try {
    console.log('[Automation] Starting embedded Playwriter CDP relay server...');
    console.log('[Automation] Extension should connect to: ws://localhost:19988/extension');

    // Start Playwriter CDP relay server embedded in grading-server
    // This runs the WebSocket server on port 19988
    // O.G.R.E extension will connect to this instead of separate Playwriter extension
    relayServer = await startPlayWriterCDPRelayServer({
      port: 19988,
      host: 'localhost',
      token: undefined, // Optional auth token
      logger: {
        log: (...args) => console.log('[Playwriter]', ...args),
        error: (...args) => console.error('[Playwriter]', ...args)
      }
    });

    mcpServerRunning = true;
    console.log('[Automation] ✓ Playwriter CDP relay server started successfully on port 19988');
    console.log('[Automation] ✓ O.G.R.E extension can now connect for browser automation');

  } catch (error) {
    console.error('[Automation] Failed to start CDP relay server:', error);
    mcpServerRunning = false;
    throw new Error(`CDP relay server initialization failed: ${error.message}`);
  }
}

/**
 * Check if MCP server is running
 */
export function isMCPServerRunning() {
  return mcpServerRunning;
}

/**
 * Stop the MCP server (called on shutdown)
 */
export async function stopMCPServer() {
  if (mcpServerRunning && relayServer) {
    console.log('[Automation] Stopping Playwriter CDP relay server...');
    relayServer.close();
    relayServer = null;
    mcpServerRunning = false;
    console.log('[Automation] ✓ CDP relay server stopped');
  }
}

// ============================================================================
// Session Management
// ============================================================================

/**
 * Grant a new automation session
 * @param {string} sessionToken - UUID generated by extension
 * @param {number} tabId - Chrome tab ID
 * @param {string} url - Page URL
 * @param {string} grantedBy - Extension ID
 * @param {Date} expiresAt - Expiration timestamp
 * @returns {SessionGrant}
 */
export function grantSession(sessionToken, tabId, url, grantedBy, expiresAt) {
  const session = {
    sessionToken,
    tabId,
    url,
    grantedBy,
    grantedAt: new Date(),
    expiresAt: new Date(expiresAt),
    scope: 'automation'
  };

  activeSessions.set(sessionToken, session);
  console.log(`[Automation] Session granted: ${sessionToken} (expires: ${session.expiresAt.toISOString()})`);

  return session;
}

/**
 * Validate a session token
 * @param {string} sessionToken
 * @returns {SessionGrant}
 * @throws {Error} if session is invalid or expired
 */
export function validateSession(sessionToken) {
  const session = activeSessions.get(sessionToken);

  if (!session) {
    throw new Error('Invalid session token');
  }

  if (Date.now() > session.expiresAt.getTime()) {
    activeSessions.delete(sessionToken);
    throw new Error('Session expired');
  }

  return session;
}

/**
 * Revoke a session
 * @param {string} sessionToken
 */
export function revokeSession(sessionToken) {
  const deleted = activeSessions.delete(sessionToken);
  if (deleted) {
    console.log(`[Automation] Session revoked: ${sessionToken}`);
  }
  return deleted;
}

/**
 * Clean up expired sessions (run periodically)
 */
export function cleanupExpiredSessions() {
  const now = Date.now();
  let cleaned = 0;

  for (const [token, session] of activeSessions.entries()) {
    if (now > session.expiresAt.getTime()) {
      activeSessions.delete(token);
      cleaned++;
    }
  }

  if (cleaned > 0) {
    console.log(`[Automation] Cleaned up ${cleaned} expired session(s)`);
  }
}

// Run cleanup every 5 minutes
setInterval(cleanupExpiredSessions, 5 * 60 * 1000);

// ============================================================================
// DOM Extraction (from grade-selectors.md)
// ============================================================================

/**
 * Extract rubric and student data from the grading page
 * Uses Playwriter MCP to execute code in the browser
 *
 * @param {string} sessionToken - Valid session token
 * @returns {Promise<{rubric: Object, students: Array}>}
 */
export async function extractGradingData(sessionToken) {
  const session = validateSession(sessionToken);
  const client = getMCPClient();

  console.log(`[Automation] Extracting data from ${session.url}`);

  // Navigation step (optional - assumes user is already on the page)
  // Uncomment if you need to navigate first:
  // await client.callTool({
  //   name: 'playwriter_execute',
  //   arguments: {
  //     code: `
  //       await page.goto('${session.url}');
  //       await page.waitForSelector('div[data-lastchange]');
  //     `
  //   }
  // });

  // Extract all data in ONE MCP call
  const extractResult = await client.callTool({
    name: 'playwriter_execute',
    arguments: {
      code: `
        const students = Array.from(document.querySelectorAll('div[data-lastchange]'));
        const first = students[0];
        const firstRegion = first.querySelector('div[role="region"]');
        const part1Div = firstRegion.children[1];
        const promptDiv = part1Div.children[0];
        const part2Div = firstRegion.children[3];

        // Grading checklist (collapsed <details> in Part 1)
        const checkDiv = promptDiv.querySelector('details')?.querySelector('div');
        const checklistItems = checkDiv
          ? Array.from(checkDiv.querySelectorAll('tr')).map(tr => ({
              category: tr.querySelector('b')?.textContent.trim() || '',
              items: Array.from(tr.querySelectorAll('label')).map(l => l.textContent.trim())
            })).filter(x => x.category || x.items.length)
          : [];

        // Rubric targets and model response (collapsed <details> in Part 2)
        const rubDiv = part2Div?.querySelector('details')?.querySelector('div');
        const rubricItems = rubDiv
          ? Array.from(rubDiv.querySelectorAll('tr')).map(tr => ({
              category: tr.querySelector('b')?.textContent.trim() || '',
              items: Array.from(tr.querySelectorAll('li')).map(l => l.textContent.trim())
            })).filter(x => x.category || x.items.length)
          : [];
        const modelText = rubDiv?.querySelector('div')?.textContent.trim() || null;

        // Essay prompt
        const promptPs = promptDiv.querySelectorAll(':scope > p, :scope > div > p');
        const essayPrompt = Array.from(promptPs).map(p => p.textContent.trim()).join(' ').substring(0, 500);

        // Max score from score input parent text
        const scoreInput = first.querySelector('input[aria-label="Score"]');
        const maxMatch = scoreInput.parentElement.textContent.match(/\\/(\d+\\.?\d*)/);
        const maxScore = maxMatch ? parseFloat(maxMatch[1]) : 10;

        // All student data in one pass
        const studentData = students.map((s, i) => {
          const region = s.querySelector('div[role="region"]');
          const responseDiv = region?.children[1]?.children[1];
          return {
            index: i,
            name: s.querySelector('b').textContent.trim(),
            currentScore: s.querySelector('input[aria-label="Score"]').value,
            hasFeedback: (s.querySelector('div.fbbox[role="textbox"]')?.textContent.trim().length || 0) > 0,
            response: responseDiv?.textContent.trim() || ''
          };
        });

        return {
          rubric: { essayPrompt, checklistItems, rubricItems, modelText, maxScore },
          students: studentData
        };
      `
    }
  });

  const data = JSON.parse(extractResult.content);
  console.log(`[Automation] Extracted rubric and ${data.students.length} students`);

  return data;
}

// ============================================================================
// Page Filling (from grade-selectors.md)
// ============================================================================

/**
 * Fill grades and feedback for a batch of students
 * Uses Playwriter MCP to manipulate the DOM
 *
 * @param {string} sessionToken - Valid session token
 * @param {Array<{studentIndex: number, score: number, feedback: string}>} results
 * @returns {Promise<void>}
 */
export async function fillGrades(sessionToken, results) {
  const session = validateSession(sessionToken);
  const client = getMCPClient();

  console.log(`[Automation] Filling ${results.length} student grades`);

  // Fill grades using Playwriter execute (batch of 5 recommended)
  await client.callTool({
    name: 'playwriter_execute',
    arguments: {
      code: `
        const results = ${JSON.stringify(results)};
        const studentSections = Array.from(document.querySelectorAll('div[data-lastchange]'));

        for (const r of results) {
          const section = studentSections[r.studentIndex];
          if (!section) {
            console.error('Student section not found:', r.studentIndex);
            continue;
          }

          // Scroll into view for visual feedback
          section.scrollIntoView({ behavior: 'smooth', block: 'center' });
          await new Promise(resolve => setTimeout(resolve, 200));

          // Set score
          const scoreInput = section.querySelector('input[aria-label="Score"]');
          if (scoreInput) {
            scoreInput.value = String(r.score);
            scoreInput.dispatchEvent(new Event('input', { bubbles: true }));
            scoreInput.dispatchEvent(new Event('change', { bubbles: true }));
          }

          // Set feedback (TinyMCE pattern: set BOTH contenteditable div AND hidden input)
          const fbBox = section.querySelector('div.fbbox[role="textbox"]');
          const hidden = section.querySelector('input[type="hidden"][name^="fb-"]');
          const html = '<p>' + r.feedback + '</p>';

          if (fbBox) {
            fbBox.innerHTML = html;
            fbBox.dispatchEvent(new Event('input', { bubbles: true }));
          }
          if (hidden) {
            hidden.value = html;
          }
        }

        // Click Quick Save button
        const saveBtn = Array.from(document.querySelectorAll('button'))
          .find(btn => btn.textContent.includes('Quick Save'));
        if (saveBtn) {
          saveBtn.click();
          console.log('Clicked Quick Save');
        } else {
          console.warn('Quick Save button not found');
        }
      `
    }
  });

  console.log(`[Automation] Filled ${results.length} grades and clicked save`);
}
